// AI Chief Phase 1: normalize backend Email rows -> EmailIngestItem subset.
// Whitelist only the schema fields; drop body_html/non-ingest fields (privacy).
const items = $input.all();
const out = [];
for (const item of items) {
  const r = item.json || item || {};
  const arr = Array.isArray(r) ? r : (Array.isArray(r.data) ? r.data : (Array.isArray(r.results) ? r.results : [r]));
  for (const e of arr) {
    if (!e || !e.message_id) continue;
    out.push({
      json: {
        message_id: String(e.message_id),
        thread_id: e.thread_id ? String(e.thread_id) : null,
        from_email: e.from_email ? String(e.from_email) : null,
        from_name: e.from_name ? String(e.from_name) : null,
        to_email: e.to_email ? String(e.to_email) : null,
        subject: e.subject ? String(e.subject) : '',
        body_text: e.body_text ? String(e.body_text).slice(0, 4000) : '',
        received_at: e.received_at ? String(e.received_at) : null,
        is_read: !!e.is_read
      }
    });
  }
}
return out.length ? out : [{ json: { message_id: "__none__", from_email: null, subject: "(no rows)", body_text: null, is_read: false } }];

// AI Chief Phase 1: report inserted/ignored/failed to verify the round trip.
// Ingest node returns the parsed JSON body directly as $json (not fullResponse).
const items = $input.all();
const results = [];
for (const it of items) {
  const b = it.json || it;
  const arr = Array.isArray(b.results) ? b.results : (Array.isArray(b.body && b.body.results) ? b.body.results : []);
  for (const res of arr) results.push(res);
}
const inserted = results.filter(r => r && r.status === "inserted").length;
const ignored = results.filter(r => r && r.status === "ignored").length;
return [{
  json: {
    received: results.length,
    inserted,
    ignored,
    failed: Math.max(0, results.length - inserted - ignored),
    details: results
  }
}];
